import{_ as t,o as a,c as r,ag as n}from"./chunks/framework.2cFhd8Ux.js";const g=JSON.parse('{"title":"Week 15 — Ship and Reflect","description":"","frontmatter":{"source":"weeks/15-ship-and-reflect/README.md"},"headers":[],"relativePath":"weeks/15-ship-and-reflect/index.md","filePath":"weeks/15-ship-and-reflect/index.md"}'),o={name:"weeks/15-ship-and-reflect/index.md"};function i(s,e,l,d,h,c){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="week-15--ship-and-reflect" tabindex="-1">Week 15 — Ship and Reflect <a class="header-anchor" href="#week-15--ship-and-reflect" aria-label="Permalink to &quot;Week 15 — Ship and Reflect&quot;">​</a></h1><blockquote><p>The last teaching week: freeze a contribution you can demonstrate and defend, look honestly at where the field is going and how sure anyone can be, and decide what you would now never delegate.</p></blockquote><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p><strong>No quiz, no oral exam, nothing exam-like this week.</strong> University Regulation H-1-a says: &quot;No quizzes or exams may be given in lecture-recitation periods during the week before finals week.&quot; Week 15 is that week. The Lab&#39;s defense dry run is practice: nothing in it is scored or recorded. The final defense itself is in finals week (<a href="./../16-final-defense/">week 16</a>).</p></div><h2 id="this-week-at-a-glance" tabindex="-1">This week at a glance <a class="header-anchor" href="#this-week-at-a-glance" aria-label="Permalink to &quot;This week at a glance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Details</th></tr></thead><tbody><tr><td><strong>Before the Seminar</strong></td><td>The reading and your response; the staff comments on your report draft; CS [5xxx]: study-talk slides to the instructor 24 hours ahead</td></tr><tr><td><strong>Seminar</strong></td><td>Where the field is going, with the uncertainty left in · CS [5xxx] <strong>empirical-study talks</strong> (10 minutes each) · the course retrospective. No quiz</td></tr><tr><td><strong>Lab</strong></td><td>Final <strong>integration sprint</strong> and a <code>final-rc</code> tag · a one-page demo script · a <strong>defense dry run</strong> with a partner team and peer feedback (not graded) (<a href="./lab.html">Week 15 — Lab and Assignment</a>)</td></tr><tr><td><strong>Due before next week&#39;s Seminar</strong></td><td>There&#39;s no Seminar in finals week. The <code>final</code> tag is due <strong>before the start of the final exam slot</strong>; the final report, peer evaluation 3 and the CS [5xxx] final paper by <strong>11:59 pm on the last day of finals week</strong> (<a href="./lab.html#assignment--ready-for-the-final">assignment</a>)</td></tr><tr><td><strong>AI use this week</strong></td><td>🟢 AI on: fixes during the sprint · 🟡 AI limited: the final report (AI may help with tables, figures and checking claims; limitations, contributions and reflection are the team&#39;s) · 🔴 AI off: the reading response, the retrospective survey, dry-run questions and feedback cards, peer evaluation 3, answering questions in a study talk</td></tr><tr><td><strong>Reading</strong></td><td>Kwa et al., &quot;Measuring AI Ability to Complete Long Software Tasks&quot; (<a href="#reading">below</a>)</td></tr><tr><td><strong>Reading response</strong></td><td>150–250 words, 🔴 AI off, on Canvas, before the Seminar (<a href="#reading">prompt</a>)</td></tr><tr><td><strong>Team project</strong></td><td>Integrate, freeze, rehearse; the <code>final</code> tag and the final report (<a href="./../../project/milestones.html#final">milestones</a>)</td></tr><tr><td><strong>Graduate track</strong></td><td><strong>Study talks</strong> in the Seminar; with more than about four, they continue into the Lab. A presentation is not an exam, so Regulation H-1-a allows it (<a href="./../../graduate/empirical-study.html#talk-20-points-2">talk rubric</a>). Final paper in finals week</td></tr><tr><td><strong>Time</strong></td><td>Seminar and Lab 2.5 h · outside about 6 h (CS [5xxx]: about 7.5 h)</td></tr></tbody></table><h2 id="learning-objectives" tabindex="-1">Learning objectives <a class="header-anchor" href="#learning-objectives" aria-label="Permalink to &quot;Learning objectives&quot;">​</a></h2><p>By the end of this week you can:</p><ol><li><strong>Read a trend claim critically:</strong> separate what was measured from what is extrapolated, and state a forecast with a probability and a way to check it.</li><li><strong>Integrate and freeze</strong> a contribution: a release candidate that builds from scratch and reproduces every number in your report.</li><li><strong>Present a contribution as evidence</strong> in six minutes: behavior shown live, one check rerun, one limitation stated before anyone asks.</li><li><strong>Give and use peer feedback</strong> on a demo and on answers to questions.</li><li><strong>Reflect on Specify · Delegate · Verify:</strong> what you now delegate, what you never would, and which check you&#39;ll keep using.</li></ol><h2 id="seminar" tabindex="-1">Seminar <a class="header-anchor" href="#seminar" aria-label="Permalink to &quot;Seminar&quot;">​</a></h2><p>There&#39;s no quiz. A 15-minute talk on <strong>where the field is going</strong> covers four trends, each with what has been measured, what is only extrapolated, and what would change our minds (<a href="https://boyu-zhang-uoi.github.io/engineering-software-with-ai/slides/week-15.html" target="_blank" rel="noreferrer">slides</a>); you write three forecasts of your own, each with a probability and a way to check it in a year.</p><p>Then come the CS [5xxx] <strong>empirical-study talks</strong>: 10 minutes each plus 2–3 minutes of questions, which undergraduates ask (participation).</p><p>The Seminar ends with the <strong>course retrospective</strong>: an anonymous, ungraded survey on Canvas (🔴 AI off) and a discussion of what to keep, drop or change, and of one question: <em>what would you now never delegate to an agent, and why?</em></p><h2 id="lab" tabindex="-1">Lab <a class="header-anchor" href="#lab" aria-label="Permalink to &quot;Lab&quot;">​</a></h2><p>The last Lab gets your team ready for finals week (<a href="./lab.html">Week 15 — Lab and Assignment</a>):</p><ul><li><strong>Integration sprint:</strong> merge or close every open PR (reviewed, CI green), freeze features, tag a release candidate <code>final-rc</code>, and rerun the grader&#39;s walk from week 14 on it.</li><li><strong>Demo script:</strong> one page with a fallback for every step.</li><li><strong>Dry run:</strong> your six-minute demo for a partner team, which asks practice questions and writes feedback cards. Nothing is scored or recorded, and anyone may say &quot;pass&quot;.</li></ul><h2 id="reading" tabindex="-1">Reading <a class="header-anchor" href="#reading" aria-label="Permalink to &quot;Reading&quot;">​</a></h2><p><strong>Read (about 40 minutes):</strong> Kwa et al., <a href="https://arxiv.org/abs/2503.14499" target="_blank" rel="noreferrer">&quot;Measuring AI Ability to Complete Long Software Tasks&quot;</a> (NeurIPS 2025): the abstract, the introduction, the main figure of time horizons over time, and the limitations. If you read it in week 1 or presented it, read Kleppmann&#39;s <a href="https://martin.kleppmann.com/2025/12/08/ai-formal-verification.html" target="_blank" rel="noreferrer">&quot;Prediction: AI will make formal verification go mainstream&quot;</a> instead.</p><p><strong>Reading response</strong> (150–250 words, 🔴 AI off, on Canvas, before the Seminar): Say what the 50% <a href="./../../resources/glossary.html#time-horizon">time horizon</a> measures, with the paper&#39;s doubling rate. Give one reason, from evidence elsewhere in this course, why a longer horizon might not mean your team can delegate longer tasks. Then say what <em>would</em> make you delegate more, and end with one question for the Seminar (<a href="./../../assessment/rubrics.html#reading-response-5-points">rubric</a>). For Kleppmann, the same with his claim that specifications become the bottleneck.</p><h2 id="key-ideas" tabindex="-1">Key ideas <a class="header-anchor" href="#key-ideas" aria-label="Permalink to &quot;Key ideas&quot;">​</a></h2><ul><li><strong>A trend in a benchmark is not a forecast of your job.</strong> The length of task that agents complete half the time has doubled roughly every 7 months since 2019 (<a href="https://arxiv.org/abs/2503.14499" target="_blank" rel="noreferrer">Kwa et al.</a>). But those tasks have automatic checks, and maintainers merged far fewer test-passing agent PRs than an automated grader accepted, 24.2 points fewer (<a href="https://metr.org/notes/2026-03-10-many-swe-bench-passing-prs-would-not-be-merged-into-main/" target="_blank" rel="noreferrer">METR</a>). The limit on what you can delegate is what you can verify.</li><li><strong>Verification is becoming the work.</strong> LLMs produced formally verified Dafny code for 82% of 12,504 specifications, and pure Dafny verification rose from 68% to 96% in a year (<a href="https://arxiv.org/abs/2509.22908" target="_blank" rel="noreferrer">Bursuc et al.</a>; <a href="https://martin.kleppmann.com/2025/12/08/ai-formal-verification.html" target="_blank" rel="noreferrer">Kleppmann</a>); Kleppmann argues that writing specifications becomes the bottleneck. This course&#39;s specs, properties, mutation scores and evals are that skill.</li><li><strong>Adoption is broad, and its effects on careers are unsettled.</strong> An estimated 22.2–28.7% of 128,018 GitHub projects had adopted agents (<a href="https://arxiv.org/abs/2601.18341" target="_blank" rel="noreferrer">Robbes et al.</a>). Employment of developers aged 22–25 fell nearly 20% from its late-2022 peak, but under stricter controls the decline is significant only after 2024 and partly has non-AI causes (<a href="https://digitaleconomy.stanford.edu/news/canaries-interest-rates-and-timinga-more-on-recent-drivers-of-employment-changes-for-young-workers" target="_blank" rel="noreferrer">Brynjolfsson et al.</a>).</li><li><strong>Norms keep moving.</strong> In one term the Linux kernel dropped its AI tag requirement and QEMU debated relaxing its ban (<a href="./../../resources/case-studies.html#maintainers-ai-policies">cases E1–E8</a>). Read the current policy, not a summary.</li><li><strong>Tools churn; the loop lasts.</strong> Several free tiers the course used changed during the year (<a href="./../../TOOLS.html#risks-and-recent-changes">Tool Handout: Risks and recent changes</a>); <a href="./../../resources/safe-loop.html#specify--delegate--verify">Specify · Delegate · Verify</a>, observed-or-inferred claims, tests that fail without the change, and disclosure didn&#39;t.</li><li><strong>Done means defensible.</strong> The final defense counts &quot;demonstrated behavior, reproducible checks, controlled engineering decisions, or honest limitations&quot; and not feature count (<a href="./../../project/final-defense.html#the-principle">the principle</a>).</li></ul><h2 id="check-your-understanding" tabindex="-1">Check your understanding <a class="header-anchor" href="#check-your-understanding" aria-label="Permalink to &quot;Check your understanding&quot;">​</a></h2><ol><li>The time horizon doubled again. What else would you need to know before delegating a task twice as long?</li><li>Which of your forecasts would surprise you most, and what evidence would you see first?</li><li>Your <code>final-rc</code> builds in your Codespace but not in a fresh one. What&#39;s the likely cause, and why does it matter for the grade?</li><li>In the dry run, the partner team asked a question you couldn&#39;t answer. What should go in your preparation, and what should go in your report&#39;s limitations?</li></ol><h2 id="if-a-tool-is-down" tabindex="-1">If a tool is down <a class="header-anchor" href="#if-a-tool-is-down" aria-label="Permalink to &quot;If a tool is down&quot;">​</a></h2><ul><li><strong>Codespaces won&#39;t start:</strong> a dev container on a laptop (<a href="./../../setup/sandboxes.html">sandboxes</a>); in the dry run, show the CI run on <code>final-rc</code> instead of a live rerun.</li><li><strong>CI is slow or out of minutes:</strong> rerun the check locally and keep the last green CI run as the fallback (<a href="./../../resources/troubleshooting.html#ci-minutes-and-failing-workflows">troubleshooting</a>).</li><li><strong>An agent or free tier is unavailable:</strong> you&#39;re integrating, not building: work by hand, or switch tools (<a href="./../../TOOLS.html">Tool Handout</a>).</li><li><strong>Canvas is down for the survey:</strong> it stays open until the end of finals week.</li></ul><h2 id="going-further" tabindex="-1">Going further <a class="header-anchor" href="#going-further" aria-label="Permalink to &quot;Going further&quot;">​</a></h2><ul><li>The UT Austin <a href="https://www.cs.utexas.edu/~witchel/378AC/index.html" target="_blank" rel="noreferrer">CS 378</a> and Michigan <a href="https://eecs498-aase.github.io/syllabus.html" target="_blank" rel="noreferrer">EECS 498</a> course pages: compare what other courses chose to teach.</li><li>Yu &amp; Moon, <a href="https://arxiv.org/abs/2607.17067" target="_blank" rel="noreferrer">&quot;Who Will Become the Next Senior?&quot;</a>, AIES 2026.</li><li>OWASP, <a href="https://genai.owasp.org/resource/owasp-genai-llm-top-10-2026/" target="_blank" rel="noreferrer">GenAI LLM Top 10 2026</a>: Excessive Agency rose to third.</li><li>The <a href="./../../resources/reading-list.html#week-15--ship-and-reflect">week 15 reading list</a>.</li></ul>',26)])])}const f=t(o,[["render",i]]);export{g as __pageData,f as default};
